-- 20강 테이블 생성하기
-- H2 콘솔(localhost:8082)에 jdbc:h2:tcp://localhost/~/test 로 접속해서 실행
drop table if exists member CASCADE;
create table member
(
    -- generated by default as identity : id 를 안 넣고 insert 하면 DB 가 값을 채워줌
    id   bigint generated by default as identity,
    name varchar(255),
    primary key (id)
);

